def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1 and history[0][0] == 'C' and history[0][1] == 'D':
        return 'D'

    total_d = 0
    win = n if n < 15 else 15
    recent_start = n - win
    recent_d = 0
    for i in range(n):
        op = history[i][1]
        if op == 'D':
            total_d += 1
            if i >= recent_start:
                recent_d += 1

    if total_d == 0:
        return 'C'
    if total_d == n:
        return 'D'

    unprov = 0
    forg = 0
    ret = 0
    for i in range(n):
        my, op = history[i]
        if op == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                unprov += 1
        if i > 0 and history[i - 1][0] == 'D':
            if op == 'C':
                forg += 1
            else:
                ret += 1

    hard = False
    if win >= 10 and recent_d >= 6:
        hard = True
    elif win >= 8 and recent_d >= 5 and total_d * 2 > n:
        hard = True
    if n <= 5 and total_d >= 3:
        hard = True
    if hard:
        return 'D'

    last_my, last_opp = history[-1]
    prev_my = history[-2][0] if n >= 2 else 'C'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_d >= 6:
                return 'D'
            return 'C'

        if prev_my == 'D':
            return 'C'

        threshold = 2
        if ret > forg:
            threshold = 5 + (ret - forg)
            if threshold > 8:
                threshold = 8

        if unprov >= threshold or recent_d >= 5:
            return 'D'
        return 'C'

    if last_my == 'D' and forg > ret and unprov >= 3 and recent_d <= 3:
        streak = 0
        i = n - 1
        while i >= 0 and history[i][0] == 'D':
            streak += 1
            i -= 1
        if streak == 1:
            return 'D'

    return 'C'
